INSERT INTO SYS_USER_ROLE(USERID,ROLEGUID) select t.* from(
( select #{item.userid,jdbcType=VARCHAR} userid , #{item.roleguid,jdbcType=VARCHAR} roleguid from dual )
)t

INSERT INTO SYS_MENU_DESKTOP(GUID,USERID,MENUGUID,SORT) select t.* from(
( select #{item.guid,jdbcType=VARCHAR} guid , #{item.userid,jdbcType=VARCHAR} userid , #{item.menuguid,jdbcType=VARCHAR} menuguid, #{index} sort from dual )
) t
